// Telegram sends the same photo at several resolutions in message.photo, sorted smallest to
// largest -- take the last one (highest resolution) for the clearest read on small receipt print.
// PDFs arrive as message.document instead -- no resolution choice, just use it directly.
if (Array.isArray($json.message.photo) && $json.message.photo.length > 0) {
  const photos = $json.message.photo;
  const largest = photos[photos.length - 1];
  return [{ json: { chatId: $json.message.chat.id, fileId: largest.file_id, mediaType: 'image/jpeg', anthropicType: 'image' } }];
}
const doc = $json.message.document;
return [{ json: { chatId: $json.message.chat.id, fileId: doc.file_id, mediaType: doc.mime_type, anthropicType: 'document' } }];

const results = [];
const source = $('Pick Largest Photo').first().json;
for (let i = 0; i < $input.all().length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  results.push({ json: { ...$input.all()[i].json, imageBase64: buffer.toString('base64'), mediaType: source.mediaType, anthropicType: source.anthropicType }, binary: $input.all()[i].binary });
}
return results;

