// Validates the LLM's extraction before any of it is trusted — never a bare
// extract-and-trust path, same rule as the Price Refresh Agent's Validate Extraction node.
let source = 'telegram';
try { $('Web Upload Trigger').first(); source = 'web'; } catch (e) {}

let parsed;
try {
  const raw = $input.first().json.content?.find((b) => b.type === 'text')?.text ?? '';
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { valid: false, reason: 'unparseable JSON from extraction', source } }];
}

const storeOk = typeof parsed.store === 'string' && parsed.store.length > 0;
const rawItems = Array.isArray(parsed.items) ? parsed.items : [];
const validItems = rawItems.filter((i) => typeof i.item === 'string' && i.item.length > 0 && typeof i.price === 'number' && i.price > 0);
const skippedCount = rawItems.length - validItems.length;

if (!storeOk || validItems.length === 0) {
  return [{ json: { valid: false, reason: 'missing/invalid required field', raw: parsed, source } }];
}

const date = (typeof parsed.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(parsed.date))
  ? parsed.date
  : $now.toFormat('yyyy-MM-dd');

return [{ json: { valid: true, store: parsed.store, date, items: validItems, skippedCount, source } }];

// Flattens one split-out item back into a single row shape carrying the receipt-level
// store/date alongside its own item/price/category/size/unit_label.
const receipt = $('Validate Extraction').first().json;
const item = $json;
return [{ json: {
  item: item.item,
  category: item.category || 'Household',
  store: receipt.store,
  price: item.price,
  size: item.size || '',
  unit_label: item.unit_label || '',
  date: receipt.date
} }];

// Runs once for all split items (named reference back to Validate Extraction, not the
// split branch, so this isn't affected by however many rows the receipt had).
// $('Pick Largest Photo') never executed on a web-uploaded run -- guard it so this
// node can't crash the whole execution (that would also take down the parallel
// Format Web Response branch, since n8n halts on any unhandled node error).
const receipt = $('Validate Extraction').first().json;
const lines = receipt.items.map((i) => {
  const flag = (!i.size) ? ' \u26a0\ufe0f no size printed' : '';
  return `\u2022 ${i.item} \u2014 $${i.price.toFixed(2)}${flag}`;
}).join('\n');
const total = receipt.items.reduce((sum, i) => sum + i.price, 0);
const skippedNote = receipt.skippedCount > 0 ? `\n\n\u26a0\ufe0f ${receipt.skippedCount} line(s) skipped \u2014 unreadable price.` : '';
const text = `Logged ${receipt.items.length} item(s) from ${receipt.store} (${receipt.date}), total $${total.toFixed(2)}:\n\n${lines}${skippedNote}`;
let chatId = null;
try { chatId = $('Pick Largest Photo').first().json.chatId; } catch (e) {}
return [{ json: { chatId, text } }];

// Web-uploaded receipts arrive as raw JSON (the app already has the file as base64
// client-side, no Telegram file_id/download step needed here).
const body = $json.body || $json;
const mediaType = body.mediaType;
const anthropicType = mediaType === 'application/pdf' ? 'document' : 'image';
return [{ json: { imageBase64: body.imageBase64, mediaType, anthropicType, source: 'web' } }];

// Builds the HTTP error response for web-triggered uploads. Harmless no-op when this
// run came from Telegram instead -- Respond to Webhook silently ignores it since there's
// no pending webhook call to answer. Always shows a friendly message -- the internal
// reason ('unparseable JSON from extraction' etc.) is for our own debugging, not the user.
return [{ json: { ok: false, reason: "Couldn't read that receipt clearly. Try a flatter, better-lit photo, or make sure the whole receipt is in frame." } }];

// Runs once for all split items (named reference back to Validate Extraction, same
// pattern as Format Confirmation Message). Harmless no-op when this run came from
// Telegram instead -- Respond to Webhook silently ignores it.
const receipt = $('Validate Extraction').first().json;
const total = receipt.items.reduce((sum, i) => sum + i.price, 0);
return [{ json: {
  ok: true,
  store: receipt.store,
  date: receipt.date,
  itemsLogged: receipt.items.length,
  total: Math.round(total * 100) / 100,
  skippedCount: receipt.skippedCount,
  items: receipt.items
} }];
